import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { readZipEntries } from './zip-archive.mjs';

/** Validate generated bytes, including the bundled license, before any upload. */
export function validatePackage({
  packagePath,
  packageId,
  version,
  licensePath = 'LICENSE',
  licenseExpression = 'Unlicense',
}) {
  if (!packageId || !version)
    throw Error('Expected package identity/version is required');
  const entries = readZipEntries(readFileSync(packagePath));
  const specs = [...entries.keys()].filter((name) => name.endsWith('.nuspec'));
  if (specs.length !== 1 || specs[0].includes('/'))
    throw Error('Expected exactly one root nuspec');
  // Let the platform XML parser handle XML syntax/entities, with DTD disabled.
  const result = spawnSync(
    'dotnet',
    [
      'msbuild',
      'scripts/validate-nuspec.proj',
      '-nologo',
      `-property:ExpectedId=${packageId}`,
      `-property:ExpectedVersion=${version}`,
      `-property:ExpectedLicense=${licenseExpression}`,
      `-property:PackageFile=${resolve(packagePath)}`,
    ],
    { encoding: 'utf8', maxBuffer: 1024 * 1024 },
  );
  if (result.status !== 0 || result.error)
    throw Error(
      `Generated NuGet metadata validation failed: ${result.stdout || ''}${result.stderr || ''}`,
    );
  const license = entries.get('LICENSE');
  if (!license || !license.equals(readFileSync(licensePath)))
    throw Error('Bundled license bytes differ from repository LICENSE');
  if (![...entries.keys()].some((name) => /^lib\/[^/]+\/[^/]+\.dll$/.test(name)))
    throw Error('Package has no library assembly');
  return { packageId, version, packagePath };
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  validatePackage({
    packagePath: process.argv[2],
    packageId: process.env.PACKAGE_ID || '',
    version: process.env.PACKAGE_VERSION || '',
  });
